// src/jsx/Gif/GifSearchModal.jsx
import React, { useEffect, useState, useRef } from "react";
import { searchGifs, trendingGifs } from "../../../js/Chat/Gif/TenorApi.js";

export default function GifSearchModal({ onClose, onPickGif }) {
  const [query, setQuery] = useState("");
  const [gifs, setGifs] = useState([]);
  const [loading, setLoading] = useState(false);
  const [nextPos, setNextPos] = useState(null);
  const [error, setError] = useState("");
  const inputRef = useRef(null);

  useEffect(() => {
    if (inputRef.current) inputRef.current.focus();
    loadTrending();
  }, []);

  const loadTrending = async (pos = null) => {
    setLoading(true);
    try {
      const r = await trendingGifs({ limit: 24, pos });
      setGifs(pos ? [...gifs, ...r.results] : r.results);
      setNextPos(r.next);
      setError("");
    } catch (err) {
      console.error(err);
      setError("Erro buscando GIFs");
    } finally {
      setLoading(false);
    }
  };

  const doSearch = async (e) => {
    if (e) e.preventDefault();
    setLoading(true);
    try {
      const r = await searchGifs(query, { limit: 24 });
      setGifs(r.results);
      setNextPos(r.next);
      setError("");
    } catch (err) {
      console.error(err);
      setError("Erro na busca");
    } finally {
      setLoading(false);
    }
  };

  const loadMore = async () => {
    if (!nextPos) return;
    setLoading(true);
    try {
      const r = query
        ? await searchGifs(query, { limit: 24, pos: nextPos })
        : await trendingGifs({ limit: 24, pos: nextPos });

      setGifs(prev => [...prev, ...r.results]);
      setNextPos(r.next);
    } catch (err) {
      console.error(err);
      setError("Erro carregando mais");
    } finally {
      setLoading(false);
    }
  };

  const pick = (gif) => {
    const media = gif?.media && gif.media[0];
    const gifUrl =
      media?.gif?.url ||
      media?.mediumgif?.url ||
      media?.tinygif?.url ||
      media?.mp4?.url ||
      null;

    if (!gifUrl) return alert("Não foi possível selecionar esse GIF.");
    onPickGif(gifUrl);
    onClose();
  };

  return (
    <div className="modal-backdrop" onMouseDown={onClose} style={{ zIndex: 3000 }}>
      <div
        className="modal-content"
        onMouseDown={(e) => e.stopPropagation()}
        style={{ maxWidth: 900, width: "95%" }}
      >
        <div style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: 10 }}>
          <form onSubmit={doSearch} style={{ flex: 1 }}>
            <input
              ref={inputRef}
              placeholder="Pesquisar GIFs (ex: comemoração, risada)"
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              style={{
                width: "100%",
                padding: "8px 12px",
                borderRadius: 6,
                border: "1px solid #ccc",
              }}
            />
          </form>

          <button onClick={() => { setQuery(""); loadTrending(); }} className="btn">
            Trending
          </button>
          <button onClick={onClose} className="btn">
            Fechar
          </button>
        </div>

        {error && <div style={{ color: "red", marginBottom: 10 }}>{error}</div>}

        <div
          style={{
            display: "grid",
            gridTemplateColumns: "repeat(auto-fill,minmax(140px,1fr))",
            gap: 8,
            maxHeight: "60vh",
            overflowY: "auto",
          }}
        >
          {gifs.map((g, i) => {
            const media = g.media && g.media[0];
            const displayUrl =
              media?.mediumgif?.url ||
              media?.gif?.url ||
              media?.tinygif?.url ||
              "";

            return (
              <div
                key={g.id || i}
                style={{ cursor: "pointer" }}
                onClick={() => pick(g)}
              >
                <img
                  src={displayUrl}
                  alt={g.title || "gif"}
                  style={{
                    width: "100%",
                    height: 120,
                    objectFit: "cover",
                    borderRadius: 6,
                  }}
                />
              </div>
            );
          })}
        </div>

        <div style={{ display: "flex", justifyContent: "center", marginTop: 10 }}>
          {loading ? (
            <span>Carregando...</span>
          ) : nextPos ? (
            <button onClick={loadMore} className="btn">
              Carregar mais
            </button>
          ) : null}
        </div>
      </div>
    </div>
  );
}
